  // Router builds the app's TitleStrategy, whose messages read this session, so an
  // eager `inject(Router)` here closes a dependency cycle (NG0200) in every app.
  private readonly injector = inject(Injector);
  private readonly platformLocation = inject(PlatformLocation);
  private userManager: UserManager | null = null;
  /** Where the identity provider puts a user's roles, from the runtime config. */
  private roleSource: Pick<PublicClientMetadata, 'rolesClaim' | 'roleMappings'> | null = null;
  private readonly currentUser = signal<User | null>(null);
  private readonly sessionLocale = signal(this.initialLocale());
